def calculate_mean(numbers: List[float]) -> float:
    return sum(numbers) / len(numbers) if numbers else raise ZeroDivisionError("Empty list, can't compute mean.")

def absolute_deviation(number: float, mean: float) -> float:
    return abs(number - mean)

def mean_absolute_deviation(numbers: List[float]) -> float:
    if len(numbers) == 0:
        raise ValueError("Empty list provided.")

    # Calculate the mean of numbers.
    mean = calculate_mean(numbers)

    # Compute absolute deviations from the calculated mean and return their average value (MAD).
    total_absolute_deviation = sum(absolute_deviation(number, mean) for number in numbers)

    return total_absolute_deviation / len(numbers) 
